void dijkstra(int s) {
    Arrays.fill(distTo, INF); distTo[s] = 0;
    pq.add(s, 0);
    while (!pq.isEmpty()) {
        int v = pq.removeSmallest();        // v's distance is now final
        for (Edge e : adj(v)) {
            int w = e.to;
            if (distTo[v] + e.weight < distTo[w]) {
                distTo[w] = distTo[v] + e.weight;
                edgeTo[w] = v;
                pq.addOrChangePriority(w, distTo[w]);
            }
        }
    }
}
